insert='''\n    private fun startReceiverQrScanner() {\n        startActivityForResult(Intent(this, QrScannerActivity::class.java).putExtra(QrScannerActivity.EXTRA_PROMPT, t("وجّه الكاميرا إلى QR تعريف هاتف الاستلام", "Point the camera at the receiver phone identification QR")), REQUEST_REPORT_RECEIVER_QR)\n    }\n\n    private fun receiverPermissionsLabel(r: com.attendpro.core.AuthorizedReportReceiver): String {\n        val items = mutableListOf<String>()\n        if (r.canReceiveReports) items += t("تقارير", "Reports")\n        if (r.canMessageEmployees) items += t("رسائل", "Messages")\n        if (r.canManageStore) items += t("إدارة المحل", "Store Management")\n        return items.joinToString(" + ").ifBlank { t("بدون صلاحيات", "No permissions") }\n    }\n\n    private fun showReceiverCenter(events: List<AttendanceEvent>) {\n        val receivers = repo.authorizedReportReceivers()\n        if (receivers.isEmpty()) { startReceiverQrScanner(); return }\n        val labels = mutableListOf(t("＋ ربط هاتف استلام جديد — فتح الكاميرا", "＋ Link new receiver phone — open camera"))\n        labels.addAll(receivers.map { "${if (it.active) "●" else "○"} ${it.name} • ${receiverPermissionsLabel(it)}" })\n        AlertDialog.Builder(this).setTitle(t("هواتف الاستلام والصلاحيات", "Receiver phones and permissions"))\n            .setItems(labels.toTypedArray()) { _, which -> if (which == 0) startReceiverQrScanner() else showReceiverActions(events, receivers[which-1]) }\n            .setNegativeButton(t("إغلاق", "Close"), null).show()\n    }\n\n    private fun showReceiverActions(events: List<AttendanceEvent>, r: com.attendpro.core.AuthorizedReportReceiver) {\n        val actions = arrayOf(\n            t("إرسال التقرير الآن", "Send report now"),\n            t("تعديل الصلاحيات", "Edit permissions"),\n            if (r.active) t("إيقاف الهاتف", "Disable phone") else t("تفعيل الهاتف", "Enable phone"),\n            t("حذف الهاتف", "Remove phone")\n        )\n        AlertDialog.Builder(this).setTitle("${r.name} • ${receiverPermissionsLabel(r)}").setItems(actions) { _, a -> when(a) {\n            0 -> if (r.active && r.canReceiveReports) shareToReceiver(events, r) else info(t("لا يمكن الإرسال", "Cannot send"), t("الهاتف موقوف أو صلاحية استلام التقارير غير مفعلة.", "The phone is disabled or report permission is off."))\n            1 -> editReceiverPermissions(events, r)\n            2 -> { repo.setReportReceiverActive(r.receiverId, !r.active); syncReceiverActive(r.receiverId, !r.active); showReceiverCenter(events) }\n            3 -> AlertDialog.Builder(this).setTitle(t("حذف الهاتف؟", "Remove phone?"))\n                .setMessage(t("سيتم سحب صلاحيات الهاتف من هذا المحل.", "This phone's Store permissions will be revoked."))\n                .setPositiveButton(t("حذف", "Remove")) { _, _ -> repo.setReportReceiverActive(r.receiverId,false); syncReceiverActive(r.receiverId,false); repo.removeReportReceiver(r.receiverId); buildUi() }\n                .setNegativeButton(t("إلغاء", "Cancel"), null).show()\n        }}.setNegativeButton(t("رجوع", "Back"), null).show()\n    }\n\n    private fun editReceiverPermissions(events: List<AttendanceEvent>, r: com.attendpro.core.AuthorizedReportReceiver) {\n        val labels = arrayOf(t("استلام التقارير", "Receive reports"), t("مراسلة الموظفين", "Message employees"), t("إدارة المحل", "Store Management"))\n        val checked = booleanArrayOf(r.canReceiveReports, r.canMessageEmployees, r.canManageStore)\n        AlertDialog.Builder(this).setTitle(t("صلاحيات ${r.name}", "${r.name} permissions"))\n            .setMultiChoiceItems(labels, checked) { _, i, v -> checked[i]=v }\n            .setMessage(t("«إدارة المحل» تمنح وظائف إدارة المحل فقط، ولا تمنح صلاحيات مالك النظام أو الإدارة المركزية.", "Store Management grants Store functions only; it does not grant System Owner or central administration privileges."))\n            .setPositiveButton(t("حفظ", "Save")) { _, _ ->\n                repo.setReportReceiverPermissions(r.receiverId, checked[0], checked[1], checked[2])\n                if (repo.isCentralActivationActive() && repo.serverUrl.isNotBlank()) Thread { CentralServerClient.setReceiverPermissions(repo.serverUrl, repo.centralAccessToken, repo.storeId, DeviceIdentity(this), r.receiverId, checked[0], checked[1], checked[2]) }.start()\n                buildUi()\n            }.setNegativeButton(t("إلغاء", "Cancel"), null).show()\n    }\n\n    private fun syncReceiverActive(receiverId: String, active: Boolean) {\n        if (repo.isCentralActivationActive() && repo.serverUrl.isNotBlank()) Thread { CentralServerClient.setReceiverActive(repo.serverUrl, repo.centralAccessToken, repo.storeId, DeviceIdentity(this), receiverId, active) }.start()\n    }\n\n    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {\n        super.onActivityResult(requestCode, resultCode, data)\n        if (requestCode != REQUEST_REPORT_RECEIVER_QR || resultCode != RESULT_OK) return\n        val invite = ReportProtocol.decodeInvite(data?.getStringExtra(QrScannerActivity.EXTRA_RESULT).orEmpty())\n        if (invite == null) { info(t("QR غير صالح", "Invalid QR"), t("اعرض QR تعريف هذا الهاتف في هاتف الاستلام ثم أعد المسح.", "Show this phone identification QR on the receiver phone and scan again.")); return }\n        if (!repo.authorizeReportReceiver(invite)) { info(t("تعذر الربط", "Link failed"), t("لم يتم قبول رمز الهاتف.", "The phone QR was not accepted.")); return }\n        repo.setReportReceiverPermissions(invite.receiverId, true, false, false)\n        if (repo.isCentralActivationActive() && repo.serverUrl.isNotBlank()) Thread {\n            val result = CentralServerClient.registerReceiver(repo.serverUrl, repo.centralAccessToken, repo.storeId, DeviceIdentity(this), invite.receiverId, invite.name, invite.secret)\n            if (result.isSuccess) CentralServerClient.setReceiverPermissions(repo.serverUrl, repo.centralAccessToken, repo.storeId, DeviceIdentity(this), invite.receiverId, true, false, false)\n            runOnUiThread {\n                if (result.isSuccess) {\n                    val grant = ReportProtocol.RemoteReceiverGrant(invite.receiverId, repo.serverUrl, repo.storeName, repo.branchId, System.currentTimeMillis()+10*60_000L)\n                    val bmp = runCatching { com.attendpro.core.QrCodeTools.bitmap(ReportProtocol.encodeRemoteGrant(grant),700) }.getOrNull()\n                    if (bmp != null) AlertDialog.Builder(this).setTitle(t("تم قبول الهاتف ✓ — QR الربط النهائي", "Phone accepted ✓ — final linking QR")).setMessage(t("الصلاحية الافتراضية: استلام التقارير فقط. بعد إكمال الربط يمكنك منح الرسائل أو إدارة المحل من مركز الصلاحيات.", "Default permission: reports only. After linking, messaging or Store Management can be granted from the permissions center.")).setView(android.widget.ImageView(this).apply { setImageBitmap(bmp); adjustViewBounds=true }).setPositiveButton(t("تم", "Done"), null).show()\n                } else info(t("تمت الإضافة محليًا", "Added locally"), t("تعذر تسجيل الخادم الآن.", "Server registration unavailable."))\n                buildUi()\n            }\n        }.start() else { info(t("تمت إضافة الهاتف", "Phone added"), t("تم حفظه محليًا بصلاحية استلام التقارير فقط.", "Saved locally with reports-only permission.")); buildUi() }\n    }\n'''
